+// Example edge worker using session tokens for stateless validation
+// The edge worker receives the public key once during initialization
+// and uses it to verify tokens without any database access
+
+import { SessionCrypto, tokenFromString } from "./session-crypto.ts";
+
+// This would be injected at deployment/initialization time
+const PUBLIC_KEY_PEM = `-----BEGIN PUBLIC KEY-----
+(public key from getSessionPublicKey())
+-----END PUBLIC KEY-----`;
+
+const sessionCrypto = new SessionCrypto(undefined, PUBLIC_KEY_PEM);
+
+export const authenticateRequest = (sessionToken: string): { sessionId: string; userId: string } | null => {
+  try {
+    const token = tokenFromString(sessionToken);
+    if (sessionCrypto.verify(token)) {
+      return { sessionId: token.sessionId, userId: token.userId };
+    }
+  } catch {
+    return null;
+  }
+  return null;
+};
+
+export const handleRequest = (request: Request): Response => {
+  const token = request.headers.get("Authorization")?.replace("Bearer ", "");
+
+  if (!token) {
+    return new Response("Unauthorized", { status: 401 });
+  }
+
+  const session = authenticateRequest(token);
+  if (!session) {
+    return new Response("Invalid or expired token", { status: 401 });
+  }
+
+  return new Response(`Hello ${session.userId}`, {
+    headers: { "Content-Type": "text/plain" },
+  });
+};
