+import { createPrivateKey, createPublicKey, sign, verify } from "crypto";
+
+export interface SessionToken {
+  sessionId: string;
+  userId: string;
+  expiresAt: number;
+  signature: string;
+}
+
+const ALGORITHM = "sha256";
+
+export class SessionCrypto {
+  private privateKey: ReturnType<typeof createPrivateKey> | null = null;
+  private publicKey: ReturnType<typeof createPublicKey> | null = null;
+
+  constructor(privateKeyPem?: string, publicKeyPem?: string) {
+    if (privateKeyPem) {
+      this.privateKey = createPrivateKey(privateKeyPem);
+      this.publicKey = createPublicKey(this.privateKey);
+    }
+    if (publicKeyPem) {
+      this.publicKey = createPublicKey(publicKeyPem);
+    }
+  }
+
+  sign(sessionId: string, userId: string, expiresAt: number): SessionToken {
+    if (!this.privateKey) throw new Error("No private key available");
+
+    const payload = `${sessionId}:${userId}:${expiresAt}`;
+    const signature = sign(ALGORITHM, Buffer.from(payload), this.privateKey).toString("base64");
+
+    return { sessionId, userId, expiresAt, signature };
+  }
+
+  verify(token: SessionToken): boolean {
+    if (!this.publicKey) throw new Error("No public key available");
+    if (Date.now() > token.expiresAt * 1000) return false;
+
+    const payload = `${token.sessionId}:${token.userId}:${token.expiresAt}`;
+    try {
+      return verify(
+        ALGORITHM,
+        Buffer.from(payload),
+        this.publicKey,
+        Buffer.from(token.signature, "base64"),
+      );
+    } catch {
+      return false;
+    }
+  }
+
+  getPublicKeyPem(): string {
+    if (!this.publicKey) throw new Error("No public key available");
+    return this.publicKey.export({ format: "pem", type: "spki" }).toString();
+  }
+}
+
+export const tokenFromString = (tokenStr: string): SessionToken => {
+  const [sessionId, userId, expiresAt, signature] = tokenStr.split(":");
+  return {
+    sessionId,
+    userId,
+    expiresAt: parseInt(expiresAt, 10),
+    signature,
+  };
+};
+
+export const tokenToString = (token: SessionToken): string => {
+  return `${token.sessionId}:${token.userId}:${token.expiresAt}:${token.signature}`;
+};
