+// Example: How to initialize the session system in the origin service
+
+import { generateKeyPairSync } from "crypto";
+import { initSessionCrypto, getSessionPublicKey, loadSession } from "./session-store.ts";
+
+// Step 1: Generate RSA key pair (done once at service startup or in a secrets setup)
+export const generateAndSetupKeys = (): { privateKey: string; publicKey: string } => {
+  const { privateKey, publicKey } = generateKeyPairSync("rsa", {
+    modulusLength: 2048,
+    publicKeyEncoding: { type: "spki", format: "pem" },
+    privateKeyEncoding: { type: "pkcs8", format: "pem" },
+  });
+
+  return {
+    privateKey: privateKey as string,
+    publicKey: publicKey as string,
+  };
+};
+
+// Step 2: Initialize the session crypto system with the private key
+export const setupOriginService = (privateKeyPem: string): void => {
+  initSessionCrypto(privateKeyPem);
+};
+
+// Step 3: When the service authenticates a user and creates a session,
+// it can now return both the session ID and a signed token
+export const authenticateUserExample = async (userId: string): Promise<{ sessionId: string; token: string }> => {
+  // In real code, this would create a session in the DB and return it
+  // For now, this is a mock example showing the API shape:
+  const mockSession = await loadSession("mock-session-id");
+
+  if (!mockSession) {
+    throw new Error("Session creation failed");
+  }
+
+  return {
+    sessionId: mockSession.id,
+    token: mockSession.token,
+  };
+};
+
+// Step 4: Expose the public key for the edge worker to download
+export const getPublicKeyEndpoint = (): string => {
+  return getSessionPublicKey();
+};
